import json, re

qs = []
q_id = 1

def add(ch, diff, q, opts, correct, expl):
    global q_id
    qs.append({
        "id": f"C{q_id:03d}",
        "subject": "Chemistry",
        "chapter": ch,
        "difficulty": diff,
        "question": q,
        "options": opts,
        "correct": correct,
        "explanation": expl
    })
    q_id += 1

