add("Coordination Compounds", "H", "Spin-only magnetic moment of [Fe(CN)6]³⁻ is: (Fe³⁺ = 3d⁵, CN⁻ is strong field ligand)", ["1.73 BM", "5.92 BM", "3.87 BM", "2.83 BM"], 0, "CN⁻ is strong field => t2g⁵ eg⁰ => 1 unpaired electron (n=1). μ = √(1*3) = √3 ≈ 1.73 BM.")
add("Coordination Compounds", "H", "Which complex is CHELATE complex with highest stability constant?", [" [Fe(edta)]⁻", "[Fe(NH3)6]³⁺", "[Fe(H2O)6]³⁺", "[FeCl6]³⁻"], 0, "EDTA⁴⁻ is a hexadentate chelating ligand forming 5 stable ring structures (Chelate effect dramatically enhances stability).")
add("Coordination Compounds", "M", "Hybridization and shape of Nickel in Ni(CO)4 (Tetracarbonylnickel) are:", ["sp³, Tetrahedral", "dsp², Square planar", "sp³d, Trigonal bipyramidal", "sp³d², Octahedral"], 0, "Ni(0) is 3d⁸ 4s². CO is strong field ligand, promoting 4s electrons into 3d to give 3d¹⁰ 4s⁰ => sp³ hybridization => Tetrahedral shape.")
