add("Hydrocarbons", "M", "Wurtz reaction of Ethyl bromide (C2H5Br) with Sodium metal in dry ether yields:", ["n-Butane", "Ethane", "Propane", "Isobutane"], 0, "2 C2H5Br + 2 Na --dry ether--> CH3-CH2-CH2-CH3 (n-Butane) + 2 NaBr.")
add("Hydrocarbons", "H", "Ozonolysis of 2-Methylbut-2-ene followed by Zn/H2O reductive workup yields:", ["Propanone (Acetone) and Ethanal (Acetaldehyde)", "Propanal and Ethanal", "Methanal and Propanone", "Butanone and Methanal"], 0, "CH3-C(CH3)=CH-CH3 + O3 --Zn/H2O--> CH3-CO-CH3 (Acetone) + CH3-CHO (Acetaldehyde).")
add("Hydrocarbons", "M", "Markownikoff's rule additions of HBr to Propene yields primary product:", ["2-Bromopropane (Isopropyl bromide)", "1-Bromopropane", "1,2-Dibromopropane", "2,2-Dibromopropane"], 0, "CH3-CH=CH2 + HBr → CH3-CH(Br)-CH3 (Electrophile H⁺ adds to CH2 to form stable 2° carbocation).")
