add("Alcohols, Phenols, & Ethers", "H", "Phenol is MORE acidic than Ethanol because:", ["Phenoxide ion is resonance stabilized", "Ethoxide ion is resonance stabilized", "Phenol has higher molecular weight", "Ethanol forms intermolecular H-bonds"], 0, "Delocalization of negative charge over benzene ring stabilizes Phenoxide ion (C6H5O⁻) relative to Phenol. Ethoxide (C2H5O⁻) has no resonance.")
add("Alcohols, Phenols, & Ethers", "H", "Hydroboration-Oxidation of Propene (CH3-CH=CH2 with B2H6 followed by H2O2 / OH⁻) yields:", ["Propan-1-ol (1-Propanol)", "Propan-2-ol (2-Propanol)", "Propane-1,2-diol", "Propanone"], 0, "Hydroboration-oxidation gives net Anti-Markownikoff addition of water: Propene → 1-Propanol.")
add("Alcohols, Phenols, & Ethers", "M", "Acid catalysed dehydration of Ethanol at 443 K (170°C) with excess Conc. H2SO4 yields:", ["Ethene (CH2=CH2)", "Diethyl ether (C2H5-O-C2H5)", "Ethanal", "Ethyl hydrogen sulfate"], 0, "At 443 K (170°C): C2H5OH --conc H2SO4--> CH2=CH2 + H2O. (At 413 K / 140°C it yields Diethyl ether).")
add("Alcohols, Phenols, & Ethers", "H", "When Phenol is treated with Bromine water (Br2/H2O), the product obtained is a white precipitate of:", ["2,4,6-Tribromophenol", "o-Bromophenol", "p-Bromophenol", "m-Bromophenol"], 0, "Polar water medium ionizes Phenol to highly reactive phenoxide ion, resulting in trisubstitution to 2,4,6-Tribromophenol.")
add("Alcohols, Phenols, & Ethers", "H", "Reaction of Anisole (C6H5-O-CH3) with concentrated HI at 373 K yields:", ["Phenol (C6H5OH) and Methyl iodide (CH3I)", "Iodobenzene and Methanol", "Phenol and Methanol", "Bromobenzene and Methyl iodide"], 0, "Cleavage of C_alkyl-O bond occurs because C_phenyl-O bond has partial double bond character: C6H5-O-CH3 + HI → C6H5OH + CH3I.")
add("Alcohols, Phenols, & Ethers", "M", "Commercial method for preparing Phenol from Cumene (Isopropylbenzene) involves oxidation followed by treatment with dilute acid to yield Phenol and byproduct:", ["Acetone (Propanone)", "Acetaldehyde", "Benzaldehyde", "Acetic acid"], 0, "Cumene --O2--> Cumene hydroperoxide --H⁺/H2O--> Phenol + CH3COCH3 (Acetone, valuable byproduct).")
add("Alcohols, Phenols, & Ethers", "H", "Kolbe's reaction: Heating Sodium phenoxide with CO2 at 400 K and 4-7 atm pressure followed by acidification yields:", ["Salicylic acid (o-hydroxybenzoic acid)", "Benzoic acid", "Salicylaldehyde", "Phthalic acid"], 0, "Sodium phenoxide + CO2 --400K, 4-7 atm--> Sodium salicylate --H⁺--> Salicylic acid (precursor to Aspirin).")

