add("Aldehydes, Ketones, & Carboxylic Acids", "H", "Hell-Volhard-Zelinsky (HVZ) reaction introduces a Chlorine or Bromine atom at α-position of Carboxylic acids using:", ["X2 (Cl2 or Br2) in presence of Red Phosphorus", "SOCl2", "PCl5", "X2 in presence of Fe"], 0, "R-CH2-COOH + X2 --Red P--> R-CH(X)-COOH + HX (alpha-halogenation of carboxylic acids with α-H).")
add("Aldehydes, Ketones, & Carboxylic Acids", "H", "Relative reactivity of carbonyl compounds towards Nucleophilic Addition reaction follows decreasing order:", ["HCHO > CH3CHO > CH3COCH3 > (C6H5)2CO", "CH3COCH3 > CH3CHO > HCHO", "(C6H5)2CO > CH3COCH3 > HCHO", "CH3CHO > HCHO > CH3COCH3"], 0, "Nucleophilic addition is favored by lower steric hindrance and strong electron-withdrawing groups: HCHO > CH3CHO > CH3COCH3 > Acetophenone > Benzophenone.")
add("Aldehydes, Ketones, & Carboxylic Acids", "M", "Decarboxylation of Sodium acetate (CH3COONa) by heating with Soda lime (NaOH + CaO) yields:", ["Methane (CH4)", "Ethane (C2H6)", "Propane", "Carbon dioxide"], 0, "CH3COONa + NaOH --CaO, Δ--> CH4 + Na2CO3 (produces alkane with one less carbon atom).")
add("Aldehydes, Ketones, & Carboxylic Acids", "H", "Wolf-Kishner reduction converts >C=O group of carbonyl compounds into >CH2 group using:", ["NH2NH2 (Hydrazine) followed by KOH in Ethylene glycol", "Zn-Hg / HCl", "LiAlH4", "H2 / Pt"], 0, "Wolf-Kishner reduction: >C=O + NH2NH2 → >C=N-NH2 --KOH/glycol, Δ--> >CH2 + N2.")

