# Verify generation count
print(f"Total chemistry questions generated: {len(qs)}")
ch_counts = {}
for q in qs:
    ch = q["chapter"]
    ch_counts[ch] = ch_counts.get(ch, 0) + 1

print(f"Chapters count ({len(ch_counts)}):")
for ch, count in ch_counts.items():
    print(f"  {ch}: {count} questions")

# Read existing questions.js
with open("questions.js", "r", encoding="utf-8") as f:
    q_code = f.read()

m = re.search(r'window\.EDUPEAK_QUESTION_BANK\s*=\s*(\{.*\});?\s*$', q_code, re.DOTALL)
if not m:
    print("Could not parse questions.js")
    exit(1)

q_bank = json.loads(m.group(1))

# OVERWRITE chemistry array cleanly with the 230 generated questions!
q_bank["chemistry"] = qs

header = """/**
 * EduPeak CEE/NEET Real Question Bank
 * Source: CEE Nepal PYQs, NEET PYQs, memory-based compilations.
 * Difficulty: 40% Medium (M), 60% Hard (H)
 */

window.EDUPEAK_QUESTION_BANK = """

new_content = header + json.dumps(q_bank, indent=2) + ';\n'

with open("questions.js", "w", encoding="utf-8") as f:
    f.write(new_content)

print(f"Successfully updated questions.js! Chemistry now has {len(q_bank['chemistry'])} questions across {len(ch_counts)} chapters!")

